"""Build the FiberHood slide: the real neighbourhood, navigable, with every reading on it.

Everything drawn is real. Buildings and streets are OpenStreetMap. The block is OSM.
The walk is the reconstruction the live API serves. All 49 readings carry the frame they
came from, the rules that fired and the measurements behind them.

    slide.html      the <section class="slide"> fragment
    slide.css       rules to append to the deck head
    slide.data.js   readings + frames, base64
"""
import base64, json, math, os

HERE = os.path.dirname(os.path.abspath(__file__))

# ---------------------------------------------------------------- the block
G = dict(door=[37.791388, -122.407837], pine=37.791201, california=37.792024,
         joice=-122.408310, stockton=-122.407585, durationS=404.1)
MPD_LAT = 111320.0
MPD_LON = 111320.0 * math.cos(G["door"][0] * math.pi / 180)

# A landscape window centred on the block — the deck frame is short and wide.
_gt = json.load(open(f"{HERE}/../photos/truth.json"))
_pos = [r for r in _gt if r["verdict"] == "locate"]
_lats = [r["lat"] for r in _pos] + [G["pine"], G["california"]]
_lons = [r["lon"] for r in _pos] + [G["joice"], G["stockton"]]
CLAT, CLON = (min(_lats) + max(_lats)) / 2, (min(_lons) + max(_lons)) / 2
_need_h = (max(_lats) - min(_lats)) * 111320.0 + 34        # 17 m of air each side
_need_w = (max(_lons) - min(_lons)) * (111320.0 * math.cos(CLAT * math.pi / 180)) + 34
ASPECT = 1.60
VIEW_H_M = max(_need_h, _need_w / ASPECT)
VIEW_W_M = VIEW_H_M * ASPECT
PX_PER_M = 1160.0 / VIEW_W_M
VB_W, VB_H = round(VIEW_W_M * PX_PER_M), round(VIEW_H_M * PX_PER_M)
LAT_N = CLAT + (VIEW_H_M / 2) / MPD_LAT
LON_W = CLON - (VIEW_W_M / 2) / MPD_LON


def X(lon):
    return round((lon - LON_W) * MPD_LON * PX_PER_M, 1)


def Y(lat):
    return round((LAT_N - lat) * MPD_LAT * PX_PER_M, 1)


d = G["door"]
# The grid here runs at 9.11 degrees, measured off 256 m of Pine Street centreline in
# OSM, and the block is the oriented bounding box of the 16 buildings standing on it.
# An axis-aligned rectangle in lat/lon was wrong by those 9 degrees, which is why the
# walk never sat on the streets.
_W = json.load(open(f"{HERE}/walk_rot.json"))
_C = _W["corners"]
LEGS = [[_C[i], _C[(i + 1) % 4]] for i in range(4)]
LENS = [math.hypot((b[1] - a[1]) * MPD_LON, (b[0] - a[0]) * MPD_LAT) for a, b in LEGS]
PERIM = sum(LENS)


def at_time(t):
    s = (t / G["durationS"]) * PERIM
    i = 0
    while i < len(LENS) - 1 and s > LENS[i]:
        s -= LENS[i]
        i += 1
    a, b = LEGS[i]
    k = min(1.0, s / LENS[i])
    lat = a[0] + (b[0] - a[0]) * k
    lon = a[1] + (b[1] - a[1]) * k
    w = math.sin(t * 0.21) * 0.7 + math.sin(t * 0.083) * 0.5
    horiz = abs(b[0] - a[0]) < abs(b[1] - a[1])
    return (lat + w / MPD_LAT, lon) if horiz else (lat, lon + w / MPD_LON)


# ---------------------------------------------------------------- OSM
osm = json.load(open(f"{HERE}/osm.json"))["elements"]
PAD = 40  # px of slack so part-visible shapes still draw


def visible(geom):
    return any(-PAD <= X(p["lon"]) <= VB_W + PAD and -PAD <= Y(p["lat"]) <= VB_H + PAD
               for p in geom)


def path_of(geom, close):
    pts = " L".join(f"{X(p['lon'])},{Y(p['lat'])}" for p in geom)
    return "M" + pts + ("Z" if close else "")


def in_block(geom):
    """Is this footprint inside the subject block?"""
    xs = [p["lon"] for p in geom]
    ys = [p["lat"] for p in geom]
    cx, cy = sum(xs) / len(xs), sum(ys) / len(ys)
    return (G["joice"] <= cx <= G["stockton"]) and (G["pine"] <= cy <= G["california"])


ROAD_M = {"secondary": 16.0, "tertiary": 14.0, "residential": 10.0,
          "living_street": 8.0, "unclassified": 9.0, "service": 5.5}

roads, blds, blds_subject = [], [], []
for e in osm:
    t = e.get("tags", {})
    g = e.get("geometry")
    if not g or not visible(g):
        continue
    if "building" in t:
        (blds_subject if in_block(g) else blds).append(path_of(g, True))
    elif t.get("highway") in ROAD_M:
        roads.append((ROAD_M[t["highway"]] * PX_PER_M, path_of(g, False),
                      t.get("highway")))

roads.sort(key=lambda r: -r[0])          # wide first, so narrow draws on top
road_sv = "\n  ".join(
    f'<path d="{p}" stroke="var(--surface)" stroke-width="{w:.0f}" fill="none" '
    f'stroke-linecap="round" stroke-linejoin="round"/>' for w, p, k in roads)
bld_sv = "\n  ".join(f'<path d="{p}"/>' for p in blds)
bld_subj_sv = "\n  ".join(f'<path d="{p}"/>' for p in blds_subject)

# ---------------------------------------------------------------- readings
pts = json.load(open(f"{HERE}/points.json"))
TOKEN = {"orange": "--comms", "yellow": "--gas", "blue": "--water",
         "green": "--sewer", "red": "--elec", "pink": "--elec", "purple": "--water",
         "white": "--ink"}
UTILITY = {"orange": "communications / fiber", "yellow": "gas, oil, steam",
           "blue": "potable water", "green": "sewer, drain", "red": "electric",
           "pink": "temporary survey", "purple": "reclaimed water"}
RULE_LABEL = {
    "stroke_width": "too thick to be a paint stroke",
    "on_pavement": "not surrounded by pavement",
    "not_vegetation": "living foliage, not pigment",
    "ground_band": "too high in frame to be on the ground",
    "pigment_coherence": "colour too mixed or dull for paint",
    "not_a_slab": "large and solid — street furniture",
    "flat_film": "shaded like a 3-D object",
}
RULE_ORDER = ["on_pavement", "stroke_width", "not_vegetation", "ground_band",
              "pigment_coherence", "not_a_slab", "flat_film"]
FIRED_ALL = {"on_pavement": 98, "stroke_width": 51, "not_vegetation": 43,
             "ground_band": 21, "pigment_coherence": 18, "not_a_slab": 1, "flat_film": 0}

frames = {}
for p in pts:
    fn = os.path.basename(p["url"])
    if fn not in frames:
        fp = f"{HERE}/small/{fn}"
        if os.path.exists(fp):
            frames[fn] = base64.b64encode(open(fp, "rb").read()).decode()

DATA = []
for p in pts:
    DATA.append({"i": p["id"].replace("wtl-ev-", ""), "t": p["t"],
                 "x": X(p["lon"]), "y": Y(p["lat"]),
                 "c": p["colour"], "v": p["verdict"], "r": p["rules"], "a": p["area"],
                 "m": dict(p["m"] or {}), "f": os.path.basename(p["url"]), "w": p["why"]})
DATA.sort(key=lambda r: r["t"])

# --- the photographs: measured EXIF GPS, judged by eye ------------------
TRUTH = json.load(open(f"{HERE}/../photos/truth.json"))
POS = [r for r in TRUTH if r["verdict"] == "locate"]
photo_b64 = {}
for r in POS:
    fp = f"{HERE}/../photos/small/{r['id']}.jpg"
    if os.path.exists(fp):
        photo_b64[r["id"]] = base64.b64encode(open(fp, "rb").read()).decode()

PHOTOS = []
for r in POS:
    PHOTOS.append({"id": r["id"], "x": X(r["lon"]), "y": Y(r["lat"]),
                   "c": (r["colours"] or ["red"])[0], "cs": r["colours"],
                   "note": r["note"], "at": r["at"][:16],
                   "lat": round(r["lat"], 6), "lon": round(r["lon"], 6)})

pmarkers = []
for r in PHOTOS:
    pmarkers.append(
        f'<g class="pk" data-p="{r["id"]}" data-c="{r["c"]}" '
        f'style="--c:var({TOKEN.get(r["c"],"--muted")})">'
        f'<circle class="hit" cx="{r["x"]}" cy="{r["y"]}" r="13"/>'
        f'<circle class="pdot" cx="{r["x"]}" cy="{r["y"]}" r="7.5"/>'
        f'</g>')

walk = [at_time(t) for t in range(0, int(G["durationS"]) + 1, 2)] + [at_time(G["durationS"])]
walk_d = "M" + " L".join(f"{X(lon)},{Y(lat)}" for lat, lon in walk)

markers = []
for r in DATA:
    cand = r["v"] == "candidate"
    markers.append(
        f'<g class="mk{" cand" if cand else ""}" data-i="{r["i"]}" data-c="{r["c"]}" '
        f'data-r="{"|".join(r["r"])}" style="--c:var({TOKEN.get(r["c"],"--muted")})">'
        f'<circle class="hit" cx="{r["x"]}" cy="{r["y"]}" r="11"/>'
        + (f'<circle class="ring" cx="{r["x"]}" cy="{r["y"]}" r="12"/>' if cand else '')
        + f'<circle class="dot" cx="{r["x"]}" cy="{r["y"]}" r="{6.5 if cand else 4.4}"/>'
        f'</g>')

dx, dy = X(G["door"][1]), Y(G["door"][0])
bx0, bx1 = X(G["joice"]), X(G["stockton"])
by0, by1 = Y(G["california"]), Y(G["pine"])

STREET_LABELS = [
    ("PINE ST", (bx0 + bx1) / 2, by1 + 9 * PX_PER_M, 0),
    ("CALIFORNIA ST", (bx0 + bx1) / 2, by0 - 6 * PX_PER_M, 0),
    ("STOCKTON ST", bx1 + 8.5 * PX_PER_M, (by0 + by1) / 2, 90),
    ("JOICE ST", bx0 - 3.5 * PX_PER_M, (by0 + by1) / 2, -90),
]
lbl_sv = "\n  ".join(
    f'<text x="{x:.0f}" y="{y:.0f}" text-anchor="middle" class="lbl"'
    + (f' transform="rotate({rot} {x:.0f} {y:.0f})"' if rot else "")
    + f'>{t}</text>' for t, x, y, rot in STREET_LABELS)

SVG = f'''<svg viewBox="0 0 {VB_W} {VB_H}" id="fhsvg" role="img"
  aria-label="Site plan of the block bounded by Pine, Joice, California and Stockton streets in San Francisco, with surrounding buildings from OpenStreetMap, the 311 metre walk, and all 49 published readings.">
  <rect x="0" y="0" width="{VB_W}" height="{VB_H}" fill="var(--paper)"/>
  <g class="roads">
  {road_sv}
  </g>
  <g class="blds">
  {bld_sv}
  </g>
  <rect class="lot" x="{bx0}" y="{by0}" width="{bx1-bx0:.1f}" height="{by1-by0:.1f}" rx="2"/>
  <g class="blds subj">
  {bld_subj_sv}
  </g>
  <path class="walk" d="{walk_d}"/>
  <g class="mks">
  {chr(10) + "  ".join(markers)}
  </g>
  <g class="pks">
  {chr(10) + "  ".join(pmarkers)}
  </g>
  <g class="door">
    <circle cx="{dx}" cy="{dy}" r="5" fill="var(--ink)"/>
    <text x="{dx+10}" y="{dy+4}" class="lbl ink">724 Pine &middot; start</text>
  </g>
  {lbl_sv}
  <g class="scale">
    <path d="M18,{VB_H-18} h{50*PX_PER_M}" stroke="var(--ink-2)" stroke-width="2"/>
    <path d="M18,{VB_H-23} v10 M{18+50*PX_PER_M},{VB_H-23} v10" stroke="var(--ink-2)" stroke-width="2"/>
    <text x="{18+25*PX_PER_M}" y="{VB_H-26}" text-anchor="middle" class="lbl">50 m</text>
  </g>
</svg>'''

# ---------------------------------------------------------------- html
cc = {}
for r in PHOTOS:
    for c in (r["cs"] or []):
        cc[c] = cc.get(c, 0) + 1
cchips = "".join(
    f'<button class="cc" data-c="{c}" style="--c:var({TOKEN.get(c,"--muted")})">'
    f'<i></i>{c}<b>{n}</b></button>' for c, n in sorted(cc.items(), key=lambda kv: -kv[1]))
rchips = "".join(
    f'<button class="rc" data-r="{code}"><span>{code}</span><b>{FIRED_ALL[code]}</b></button>'
    for code in RULE_ORDER)

HTML = f'''<section class="slide" data-t="Simulated FiberHood"><div class="si"><div class="l1" data-fold="1">
  <div class="fhhead">
    <h2 class="fht">We walked the neighbourhood and found the paint.</h2>
    <div class="fhstat">
      <span>724 Pine St, San Francisco</span><span><b>53</b>photos</span>
      <span><b>26</b>with locate paint</span><span class="zero"><b>0</b>found by the video pass</span>
    </div>
  </div>

  <div class="fh">
    <figure class="fhmap">
      <div class="lyr">
        <button class="ly on" data-l="photo">Photographs <b>26</b></button>
        <button class="ly" data-l="video">Video readings <b>49</b></button>
        <span class="lgd"><i class="m"></i>measured<i class="d"></i>derived</span>
      </div>
      {SVG}
      <figcaption class="fhcap">Buildings and streets from OpenStreetMap. The walk is fitted to the
        <b>real street grid</b> &mdash; 9.11&deg;, measured off Pine Street centreline &mdash; and to the
        oriented footprint of the 16 buildings on the block: 353&thinsp;m at 0.87&thinsp;m/s.
        Photographs sit at <b>measured</b> EXIF GPS; a phone on a hill between tall buildings is good to
        a few metres at best, so some sit off the pavement. Video readings are <b>derived</b> from that
        walk, not recorded.</figcaption>
    </figure>

    <div class="insp"><div class="inspd" id="inspd">
      <figure class="anchor"><img alt="724 Pine St, the front door the walk starts from" src="data:image/jpeg;base64,"><figcaption>724 Pine St &middot; where the walk starts</figcaption></figure>
      <p class="ik">Stage 2 &middot; Utility Locates &middot; proposed</p>
      <p class="ifind">The photographs carry GPS. The video carries context. Neither alone is the record.</p>
      <div class="signoff">
        <p class="sq">The pipeline proposes <b>0</b>. Twenty-six photographs disagree.</p>
        <p class="sm">Stage 2 &middot; Utility Locates &middot; the machine has no authority to settle this.</p>
        <div class="sbtn">
          <button class="sb ok" type="button">Confirm 0</button>
          <button class="sb no" type="button">Refuse &mdash; 26 found</button>
        </div>
      <div class="strip" id="strip"></div>
        <p class="sn" id="sn">A name is required either way. Refusals are kept, hash-chained.</p>
      </div>

    </div></div>
  </div>
</div>
<div class="more"><p class="ml">More detail</p>
  <h3 class="dh">Why a mistake costs so much here</h3>
  <p>The GC is paid <b>a fixed price per meter</b>. The fiber company buys meters of working fiber;
  it does not reimburse what it took to get them. When a sub gets it wrong, <b>you</b> pay for the
  fix, out of a margin that was thin before anyone made a mistake.</p>
  <p>Bill a meter you cannot evidence and it comes back as a clawback. Lay a meter you never billed
  and it is gone. Send a crew to a block nobody located and that crew-day is unbillable.</p>
  <h3 class="dh">The plan says marked. The block says otherwise.</h3>
  <p>The project record says stage 2 is complete &mdash; gas, water and power marked along the full
  alignment. This block disagrees. <b>That is the disagreement you want in hand before a crew
  mobilises to trench it.</b></p>
</div></div></section>'''

CSS = '''
/* ---- the FiberHood: site plan + inspector --------------------------- */
.fhhead{display:flex;align-items:baseline;gap:clamp(14px,2vw,30px);flex-wrap:wrap;margin-bottom:10px}
.fht{font-size:clamp(20px,2.3vw,31px);margin:0;max-width:24ch}
.fhstat{display:flex;gap:clamp(10px,1.5vw,20px);flex-wrap:wrap;font-family:var(--mono);
  font-size:11px;color:var(--muted);letter-spacing:.02em}
.fhstat span{display:flex;align-items:baseline;gap:5px}
.fhstat b{font-family:var(--display);font-size:clamp(16px,1.9vw,23px);color:var(--ink);font-weight:600}
.fhstat .zero b{color:var(--comms)}
.fh{display:grid;grid-template-columns:minmax(0,1.62fr) minmax(250px,1fr);
  gap:clamp(12px,1.6vw,24px);align-items:start;min-height:0}
.fhmap{margin:0;display:flex;flex-direction:column;gap:7px;min-width:0}
.fhmap svg{display:block;width:100%;height:auto;border:1px solid var(--line-strong);
  background:var(--paper)}
.fhcap{font-family:var(--mono);font-size:10px;line-height:1.5;color:var(--muted)}
.fhcap b{color:var(--gas);font-weight:600}
#fhsvg .lbl{font-family:var(--mono);font-size:11px;font-weight:600;letter-spacing:.17em;
  fill:var(--muted);paint-order:stroke;stroke:var(--paper);stroke-width:3.5;stroke-linejoin:round}
#fhsvg .lbl.ink{fill:var(--ink);letter-spacing:.03em;font-size:11px}
#fhsvg .blds path{fill:var(--sunk);stroke:var(--line);stroke-width:.7;opacity:.62}
#fhsvg .lot{fill:var(--comms);fill-opacity:.05;stroke:var(--comms);stroke-width:1.4;
  stroke-opacity:.45;stroke-dasharray:7 5}
#fhsvg.lay-photo .lot,#fhsvg.lay-photo .walk{display:none}
#fhsvg .blds.subj path{fill:var(--line-strong);stroke:var(--ink-2);stroke-width:1;opacity:1}
#fhsvg .ring{fill:none;stroke:var(--ink);stroke-width:1.6;opacity:.8}
#fhsvg .pdot{fill:var(--c);stroke:var(--paper);stroke-width:2.2;pointer-events:none;
  transition:opacity .12s ease}
#fhsvg .pk.sel .pdot{stroke:var(--ink);stroke-width:3.4;r:10}
#fhsvg .pk .hit{cursor:pointer}
#fhsvg.lay-video .pks{display:none}
#fhsvg.lay-photo .mks{display:none}
.lyr{display:flex;gap:5px;margin-bottom:6px;align-items:center;flex-wrap:wrap}
.lgd{display:flex;align-items:center;gap:5px;margin-left:auto;font-family:var(--mono);
  font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.lgd i{width:9px;height:9px;border-radius:50%;display:block}
.lgd i.m{background:var(--sewer)}
.lgd i.d{background:none;border:1.6px dashed var(--gas);margin-left:8px}
.ly{font-family:var(--mono);font-size:10.5px;padding:5px 10px;border-radius:3px;cursor:pointer;
  border:1px solid var(--line-strong);background:transparent;color:var(--ink-2);
  display:flex;gap:6px;align-items:center;line-height:1}
.ly b{color:var(--muted);font-weight:600}
.ly:hover{border-color:var(--ink-2)}
.ly.on{border-color:var(--comms);background:var(--comms);color:var(--paper)}
.ly.on b{color:var(--paper)}
.pgps{font-family:var(--mono);font-size:10px;color:var(--sewer);letter-spacing:.04em;margin:0 0 8px}
#fhsvg .walk{fill:none;stroke:var(--comms);stroke-width:2.4;stroke-linecap:round;opacity:.3}
#fhsvg.lay-video .walk{opacity:.6;stroke-width:3}
#fhsvg .hit{fill:transparent;cursor:pointer}
#fhsvg .dot{fill:var(--c);stroke:var(--paper);stroke-width:1.2;pointer-events:none;
  transition:opacity .12s ease}
#fhsvg .mk.cand .dot{stroke:var(--ink);stroke-width:2.2}
#fhsvg .mk.sel .dot{stroke:var(--ink);stroke-width:2.6}
#fhsvg.filtering .mk .dot{opacity:.12}
#fhsvg.filtering .mk.hit-f .dot{opacity:1}
.insp{background:var(--surface);border:1px solid var(--line-strong);
  padding:clamp(11px,1.3vw,17px);min-width:0;max-height:calc(100dvh - 165px);
  overflow:hidden;display:flex;flex-direction:column}
.strip{display:grid;grid-template-columns:repeat(6,1fr);gap:3px;margin:0 0 10px;
  flex:1 1 0;min-height:0;align-content:start;overflow-y:auto}
.strip button{padding:0;border:1px solid var(--line);border-top:3px solid var(--c);
  background:var(--sunk);cursor:pointer;aspect-ratio:4/3;overflow:hidden;display:block}
.strip button:hover,.strip button:focus-visible{border-color:var(--ink);outline:0}
.strip img{width:100%;height:100%;object-fit:cover;display:block}
@media (max-width:900px){.strip{grid-template-columns:repeat(8,1fr)}}
.anchor{margin:0 0 9px;display:flex;gap:9px;align-items:center}
.anchor img{width:86px;height:64px;object-fit:cover;border:1px solid var(--line-strong);display:block}
.anchor figcaption{font-family:var(--mono);font-size:10px;line-height:1.45;color:var(--muted)}
.ik{font-family:var(--mono);font-size:10px;letter-spacing:.11em;text-transform:uppercase;
  color:var(--muted);margin:0 0 7px}
.ifind{font-family:var(--display);font-size:clamp(14px,1.4vw,17px);line-height:1.2;
  color:var(--ink);margin:0 0 9px;font-weight:500}
.ihint{font-size:12.5px;line-height:1.5;color:var(--ink-2);margin:0 0 12px}
.fl{font-family:var(--mono);font-size:9.5px;letter-spacing:.11em;text-transform:uppercase;
  color:var(--muted);margin:0 0 5px}
.ccs,.rcs{display:flex;gap:4px;flex-wrap:wrap;margin:0 0 10px}
.cc,.rc{font-family:var(--mono);font-size:10px;padding:3px 7px;border-radius:3px;cursor:pointer;
  border:1px solid var(--line-strong);background:transparent;color:var(--ink-2);
  display:flex;align-items:center;gap:4px;line-height:1}
.cc i{width:7px;height:7px;background:var(--c);display:block;border-radius:1px}
.cc b,.rc b{color:var(--muted);font-weight:600}
.cc:hover,.rc:hover{border-color:var(--ink-2)}
.cc.on{border-color:var(--c);background:var(--c);color:var(--paper)}
.cc.on b{color:var(--paper)}.cc.on i{background:var(--paper)}
.rc.on{border-color:var(--comms);background:var(--comms);color:var(--paper)}
.rc.on b{color:var(--paper)}
.signoff{border-bottom:1px solid var(--line);margin:0 0 10px;padding-bottom:11px;flex:0 0 auto}
.sq b{color:var(--comms)}
.sq{font-size:13px;line-height:1.4;color:var(--ink);margin:0 0 4px;font-weight:600}
.sm{font-family:var(--mono);font-size:10.5px;color:var(--muted);margin:0 0 9px}
.sm b{color:var(--ink-2)}
.sbtn{display:flex;gap:7px;margin-bottom:8px}
.sb{font-family:var(--mono);font-size:11.5px;padding:7px 13px;cursor:pointer;border-radius:3px;
  border:1px solid var(--line-strong);background:transparent;color:var(--ink)}
.sb.ok:hover{border-color:var(--sewer);color:var(--sewer)}
.sb.no:hover{border-color:var(--elec);color:var(--elec)}
.sn{font-family:var(--mono);font-size:10px;line-height:1.5;color:var(--muted);margin:0}
.sn.warn{color:var(--gas)}
.iback{font-family:var(--mono);font-size:10px;color:var(--muted);background:none;border:0;
  padding:0;cursor:pointer;margin:0 0 8px;text-align:left}
.iback:hover{color:var(--comms)}
.ishot{width:100%;display:block;border:1px solid var(--line);margin:0 0 9px}
.ihd{display:flex;align-items:baseline;gap:7px;flex-wrap:wrap;margin:0 0 7px}
.itm{font-family:var(--display);font-size:20px;color:var(--ink);font-weight:600}
.icl{font-family:var(--mono);font-size:9px;letter-spacing:.1em;text-transform:uppercase;
  padding:3px 6px;background:var(--c);color:var(--paper);font-weight:600}
.ivd{font-family:var(--mono);font-size:9.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.iwhy{font-size:13px;line-height:1.5;color:var(--ink);margin:0 0 9px}
.imeas{font-family:var(--mono);font-size:10.5px;color:var(--muted);line-height:1.75;margin:0}
.imeas b{color:var(--ink-2);font-weight:600}
@media (max-width:900px){
  .fh{grid-template-columns:1fr}
  .insp{max-height:none}
}
'''

